// src/components/AdminMessages/ConversationList.jsx
function ConversationList({ conversations, selectedConversation, onSelectConversation, loading }) {
  const formatTime = (timestamp) => {
    if (!timestamp) return '';
    const date = new Date(timestamp);
    const now = new Date();
    const diffInHours = (now - date) / (1000 * 60 * 60);

    if (diffInHours < 24) {
      return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    } else if (diffInHours < 48) {
      return 'Hier';
    } else {
      return date.toLocaleDateString([], { month: 'short', day: 'numeric' });
    }
  };

  if (loading) {
    return (
      <div className="lg:col-span-1 bg-white rounded-xl shadow-md border border-gray-200 p-4">
        <div className="animate-pulse space-y-3">
          {[...Array(5)].map((_, i) => (
            <div key={i} className="flex space-x-3">
              <div className="rounded-full bg-gray-200 h-10 w-10"></div>
              <div className="flex-1 space-y-2">
                <div className="h-4 bg-gray-200 rounded w-3/4"></div>
                <div className="h-3 bg-gray-200 rounded w-1/2"></div>
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="lg:col-span-1 bg-white rounded-xl shadow-md border border-gray-200 p-4">
      <h3 className="font-semibold text-gray-900 mb-4">Conversations</h3>
      <div className="space-y-2 max-h-[calc(100vh-20rem)] overflow-y-auto">
        {conversations.map((conv) => (
          <div
            key={conv.id}
            onClick={() => onSelectConversation(conv)}
            className={`p-3 rounded-lg cursor-pointer transition duration-200 ${
              selectedConversation?.id === conv.id
                ? 'bg-blue-50 border border-blue-200'
                : 'hover:bg-gray-50 border border-transparent'
            } ${conv.unread_count > 0 ? 'bg-blue-25 border-l-4 border-l-blue-500' : ''}`}
          >
            <div className="flex justify-between items-start">
              <div className="flex-1">
                <div className="flex items-center space-x-2 mb-1">
                  <p className={`font-medium ${conv.unread_count > 0 ? 'text-blue-600' : 'text-gray-900'}`}>
                    {conv.first_name} {conv.last_name}
                  </p>
                  {conv.unread_count > 0 && (
                    <span className="w-2 h-2 bg-blue-500 rounded-full"></span>
                  )}
                </div>
                <p className="text-sm text-gray-600 truncate">{conv.last_message}</p>
                <p className="text-xs text-gray-500 mt-1">{conv.title}</p>
              </div>
              <div className="flex flex-col items-end space-y-1">
                <span className="text-xs text-gray-500 whitespace-nowrap">
                  {formatTime(conv.last_message_at)}
                </span>
                {conv.unread_count > 0 && (
                  <span className="bg-blue-500 text-white text-xs rounded-full w-5 h-5 flex items-center justify-center">
                    {conv.unread_count}
                  </span>
                )}
              </div>
            </div>
          </div>
        ))}

        {conversations.length === 0 && (
          <div className="text-center text-gray-500 py-8">
            Aucune conversation trouvée
          </div>
        )}
      </div>
    </div>
  );
}

export default ConversationList;
